import React, { useState, useEffect } from "react";
import "./CrosswordGame.css";

const CrosswordGame = ({
  question,
  onAnswerSubmit,
  timer,
  answerSubmitted,
  showFeedback,
  isCorrectAnswer,
  onAnswerChange,
}) => {
  const [selectedCells, setSelectedCells] = useState([]);
  const [currentDirection, setCurrentDirection] = useState("across");
  const [userInput, setUserInput] = useState("");
  const [foundWords, setFoundWords] = useState([]);
  const [attempts, setAttempts] = useState(0);
  const [startTime] = useState(Date.now());

  // Initialize grid and words safely
  const grid = question?.grid || [];
  const words = Array.isArray(question?.words) ? question.words : [];

  useEffect(() => {
    if (!answerSubmitted) {
      setSelectedCells([]);
      setUserInput("");
    }
  }, [question, answerSubmitted]);

  // Safe function to get cell class
  const getCellClass = (row, col) => {
    const cell = grid[row]?.[col];
    if (!cell || cell === "#") return "empty";

    const classes = [];
    
    // Check if cell is in selected cells
    const isSelected = selectedCells.some(
      (cellPos) => cellPos.row === row && cellPos.col === col
    );
    if (isSelected) classes.push("selecting");

    // Check if cell is part of a found word (safely)
    const isInFoundWord = foundWords.some(word => {
      if (!word?.positions) return false;
      return word.positions.some(
        pos => pos.row === row && pos.col === col
      );
    });
    
    if (isInFoundWord) classes.push("correct");

    return classes.join(" ");
  };

  const handleCellClick = (row, col) => {
    if (answerSubmitted) return;

    const cell = grid[row]?.[col];
    if (!cell || cell === "#") return;

    // Prevent selection of already correct cells
    const isAlreadyCorrect = foundWords.some(word => 
      word.positions?.some(pos => pos.row === row && pos.col === col)
    );
    if (isAlreadyCorrect) return;

    // Toggle selection logic
    const isSelected = selectedCells.some(
      (cellPos) => cellPos.row === row && cellPos.col === col
    );

    if (isSelected) {
      setSelectedCells(selectedCells.filter(
        (cellPos) => !(cellPos.row === row && cellPos.col === col)
      ));
    } else {
      setSelectedCells([...selectedCells, { row, col }]);
    }
  };

  const handleInputChange = (e) => {
    const value = e.target.value.toUpperCase();
    setUserInput(value);
    
    if (onAnswerChange) {
      onAnswerChange(value);
    }
  };

  const handleSubmit = () => {
    if (!userInput.trim() || answerSubmitted) return;

    setAttempts(prev => prev + 1);

    // Find matching word
    const matchedWord = words.find(word => 
      word.word?.toUpperCase() === userInput.toUpperCase()
    );

    if (matchedWord) {
      // Mark word as found
      setFoundWords(prev => [...prev, matchedWord]);
      
      // Check if all words are found
      if (foundWords.length + 1 >= words.length) {
        const timeTaken = (Date.now() - startTime) / 1000;
        const scoreData = {
          foundWords: foundWords.length + 1,
          totalWords: words.length,
          attempts: attempts + 1,
          timeTaken: Math.min(timeTaken, 60),
        };
        onAnswerSubmit(scoreData);
      }
      
      setUserInput("");
      setSelectedCells([]);
    }
  };

  const handleGridSubmit = () => {
    const timeTaken = (Date.now() - startTime) / 1000;
    const scoreData = {
      foundWords: foundWords.length,
      totalWords: words.length,
      attempts,
      timeTaken: Math.min(timeTaken, 60),
    };
    onAnswerSubmit(scoreData);
  };

  // Render grid safely
  const renderGrid = () => {
    if (!grid.length) {
      return <div className="crossword-error">No grid data available</div>;
    }

    return (
      <div className="crossword-grid">
        {grid.map((row, rowIndex) => (
          <div key={rowIndex} className="crossword-row">
            {row.map((cell, colIndex) => (
              <div
                key={`${rowIndex}-${colIndex}`}
                className={`crossword-cell ${getCellClass(rowIndex, colIndex)}`}
                onClick={() => handleCellClick(rowIndex, colIndex)}
              >
                {cell && cell !== "#" ? cell : ""}
              </div>
            ))}
          </div>
        ))}
      </div>
    );
  };

  return (
    <div className="crossword-question">
      <h2>Crossword Puzzle</h2>
      
      {question?.clue && (
        <div className="crossword-clue">
          <strong>Clue:</strong> {question.clue}
        </div>
      )}

      {/* Stats */}
      <div className="crossword-stats">
        <div className="stat">
          <strong>Found:</strong> {foundWords.length}/{words.length}
        </div>
        <div className="stat">
          <strong>Attempts:</strong> {attempts}
        </div>
        <div className="stat">
          <strong>Time:</strong> {Math.min(timer, 60)}s
        </div>
      </div>

      {/* Crossword Grid */}
      {renderGrid()}

      {/* Found Words */}
      {foundWords.length > 0 && (
        <div className="found-words">
          <h3>Found Words:</h3>
          <div className="words-list">
            {foundWords.map((word, index) => (
              <span key={index} className="found-word">
                {word.word}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Input Section */}
      {!answerSubmitted && foundWords.length < words.length && (
        <div className="crossword-controls">
          <input
            type="text"
            value={userInput}
            onChange={handleInputChange}
            placeholder="Enter word"
            className="answer-input"
            disabled={answerSubmitted}
          />
          <button
            className="submit-btn"
            onClick={handleSubmit}
            disabled={!userInput.trim()}
          >
            Submit Word
          </button>
          
          {/* Manual submit button for when time is running out */}
          <button
            className="submit-btn"
            onClick={handleGridSubmit}
            style={{ backgroundColor: "#667eea" }}
          >
            Finish Puzzle
          </button>
        </div>
      )}

      {/* Instructions */}
      <div className="crossword-instructions">
        <p><strong>How to play:</strong></p>
        <p>• Find words from the clue and type them in the input</p>
        <p>• Words can be horizontal, vertical, or diagonal</p>
        <p>• Click "Finish Puzzle" to submit your current progress</p>
      </div>
    </div>
  );
};

export default CrosswordGame;
